"""Archive the completed VPL A/B trials, canonical build and actual installation."""
from pathlib import Path
import hashlib,json,re,statistics,shutil
b=Path(__file__).resolve().parent.parent;root=b.parents[2]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(p):return json.loads(p.read_text())
def write(p,v):p.write_text(json.dumps(v,indent=2)+'\n')
labels=['vpl-mft-a1','vpl-direct-b1','vpl-direct-b2','vpl-mft-a2','root-vpl-frame-a1','root-vpl-latency-b1','root-vpl-latency-b2','root-vpl-frame-a2']
def table(names):
 lines=['| Trial | Distinct FPS | Median upper ms | P95 upper ms | Max upper ms |','|---|---:|---:|---:|---:|']
 for name in names:
  s=read(b/'transport/runs'/name/'summary.json');t=s['latency_high_ms'];lines.append(f"| {name} | {s['desktop_distinct_hz']:.3f} | {t['median']:.3f} | {t['p95']:.3f} | {t['max']:.3f} |")
 return '\n'.join(lines)
records=[]
for name in labels:
 p=b/'transport/runs'/name;s=read(p/'state.json');summary=read(p/'summary.json');assert summary['run_qualified']
 assert s['native_hash_before']==s['native_hash_after'] and not s['after']['processes'] and not s['after']['port'] and not s['remaining_proxies']
 assert s['before']['installed']==s['after']['installed'] and s['before']['main']==s['after']['main']=='Ready'
 assert set(read(p/'pipeline-occupancy.json')['before_submit'])=={'0'}
 nested=read(Path(s['nested_state']['root'])/'state.json');assert nested['transport_trial']=='passed' and nested['nested_stopped'] and not nested['remaining_clients']
 target=b/'transport/nested'/name;target.mkdir(parents=True,exist_ok=True)
 for file in ['state.json','compositor.log','hyprland.lua','inner.py','launch.py']:
  source=Path(s['nested_state']['root'])/file
  if source.exists():shutil.copy2(source,target/file)
 text=(p/'source.log').read_text(errors='replace');sub={int(a):int(t) for a,t in re.findall(r'profile_submit pts=(\d+).*?submit_begin=(\d+)',text)}
 elapsed=[(int(t)-sub[int(a)])/10000 for a,t in re.findall(r'profile_color_ready pts=(\d+) at=(\d+)',text) if int(a) in sub];elapsed.sort()
 records.append({'trial':name,'native_sha256':s['native_hash_before'],'encoder_backend':s['encoder_backend'],'performance_mode':s['performance_mode'],'summary':summary,'submit_to_color_ready_ms':{'n':len(elapsed),'median':statistics.median(elapsed),'p95':elapsed[int(.95*(len(elapsed)-1))]}})
write(b/'transport/vpl-comparison.json',records)
for name,count in [('vpl-candidate',68),('root-vpl',69)]:
 p=b/name;m=read(p/'method/source-sha256.json');assert m==read(p/'method/remote-source-sha256.json') and len(m)==count and all(sha(p/'source'/k)==v for k,v in m.items());assert '100% tests passed, 0 tests failed out of 6' in (p/'method/build.log').read_text()
 if name=='root-vpl':assert all(sha(root/k)==v for k,v in m.items())
encoder='source/platform/windows-reverse/vpl_encoder.cpp';assert (b/'vpl-candidate'/encoder).read_bytes()==(b/'root-vpl'/encoder).read_bytes()
write(b/'root-vpl/method/component-equivalence.json',{'vpl_encoder_cpp_sha256':sha(b/'root-vpl'/encoder),'candidate_and_canonical_encoder_implementation_identical':True,'canonical_changes':'automatic Intel HEVC selection with initialization fallback, self-contained allocator includes, public header comments/default codec, API provenance README','quality_scope':'90 common full-frame RGB markers were compared using the candidate with the identical VPL encoder implementation; canonical full transport and lifecycle are checked separately'})
for name,label in [('lifecycle-vpl','vpl'),('lifecycle-root-vpl','root-vpl')]:
 p=b/name;m=read(p/'method/windows-source-sha256.json');assert m==read(p/'method/windows-remote-source-sha256.json') and all(sha(p/k)==v for k,v in m.items());s=read(p/'runs'/label/'summary.json');assert s['qualified'] and s['frames']==s['decoded']
 (p/'README.md').write_text(f"# VPL window lifecycle and exact alpha\n\n2026-09-09. {s['frames']} recorded frames pass Linux NVDEC/CUDA/GLES decoding, all alpha bytes and metadata checks. The owned fixture changes title and location, adds another window, resizes, hides and closes windows. All seven phases appear. Both single-window direct submission and multi-window atlas composition are exercised; no input events are injected, and sampled foreground identity stays unchanged.\n\nThe native source observes frame-rate → latency → frame-rate → latency while running, with limits 4 → 1 → 4 → 1. Processes exit normally; scheduled tasks and handles are cleaned up, and the previously installed E154 binary/configuration remain unchanged during this historical trial. The canonical trial uses automatic VPL selection; the earlier candidate forces VPL. Startup and resize reinitialization are separate from steady 6K timing. This is recorded-stream lifecycle qualification, not live Wayland lifecycle or physical input acceptance.\n")
q=read(b/'vpl-quality/method/results.json');assert q['results']['mft']['frames']==q['results']['vpl']['frames']==90
for name,h in q['inputs'].items():assert sha(b/'vpl-quality/runs'/name/'stream.vfrv')==h
(b/'vpl-quality/README.md').write_text(f"# Full-frame synthetic quality comparison\n\n2026-09-09. The same 68-file candidate runs Media Foundation and VPL with the same waitable 6K fixture. All 957 MFT frames and 1181 VPL frames pass marker, opaque-alpha, NVDEC/CUDA/GLES and dimension checks. Source recordings are local-file runs, separate from full transport measurements.\n\nOn 90 common markers, every RGB pixel of each 6144×3456 frame is compared to the exact fixture shader, using the first encoded occurrence. Aggregate PSNR is {q['results']['mft']['psnr_db']:.9f} dB for MFT and {q['results']['vpl']['psnr_db']:.9f} dB for VPL. This synthetic grid shows essentially equal error; no conclusion about natural images, small text or lossless fidelity is implied. Marker lists, stream hashes, helper source/binary hashes and per-frame results are preserved.\n")
(b/'vpl-candidate/README.md').write_text('# VPL encoder candidate and paired A/B/B/A comparison\n\n2026-09-09. A single 68-file native build contains the previous Media Foundation encoder and an explicitly selected VPL backend. Six Windows CTests pass. VPL uses the existing System32 runtime, an owned external NV12 input, nominal 60 Hz/24 Mbps CBR/HEVC Main, target usage 7, one in-flight color task and two HEVC tile columns. Capture, alpha, native transport, decoder and observer binaries are kept fixed.\n\n'+table(labels[:4])+'\n\nBoth VPL trials improve distinct FPS, median and P95 versus both MFT trials in this group. This is the complete pre-draw → WGC → HEVC/exact alpha → paired QUIC → NVDEC/CUDA/GLES → nested Wayland desktop observation route. It is not physical scanout latency. VPL submit-to-color-ready medians are about 22.5–22.8 ms versus 30.1–30.2 ms with MFT; this interval is not a pure encoder hardware timer.\n\nThe 21-frame candidate lifecycle test and 90-marker full RGB comparison pass. The [canonical build](../root-vpl/README.md) then adds automatic selection and fallback and is tested separately.\n')
deployed=read(b/'vpl-deployment/method/install-state.json');assert deployed['installed'] and deployed['verified'];installed=deployed['native']['hash'];assert installed=='875E56F9E746B5DAEA37814DC67C54495A9B313CD6F0EB6B2652A59F057F42FE';assert deployed['windows_after']['hash']==installed
(b/'root-vpl/README.md').write_text('# Canonical VPL integration and actual installed build\n\n2026-09-09. All 69 local/remote build inputs match the canonical workspace at archival time. Six Windows CTests pass. Intel HEVC automatically selects VPL; failed initialization falls back to Media Foundation. Other devices/codecs retain Media Foundation. No VPL SDK installation is needed: API headers and their MIT license/provenance are vendored, while the existing System32 runtime is loaded dynamically. The current Intel runtime exposes API 2.16.\n\n'+table(labels[4:])+'\n\nAll four runs log automatic VPL selection (Intel vendor 32902, forced=0). One color task is in flight at most; every successful submission has pending=0, so the public one/four-frame admission limits are not binding here and do not establish distinct performance benefits. The mode medians/P95 cross between runs. Presentation phase contributes variation; this evidence does not certify a particular decomposition of that variation. Maximum observations above 100 ms are preserved and do not close the connection.\n\nThe canonical 20-frame lifecycle/GPU test passes all phases and three live mode changes. The VPL encoder implementation is byte-identical to the candidate used for full-frame synthetic RGB quality checks. Installed SHA256: `'+installed+'`. See [installation and rollback](../vpl-deployment/README.md). The 60 ms target remains unmet.\n')
(b/'vpl-deployment/README.md').write_text('# VPL 最优版本安装与回退\n\n2026-09-09。已把通过规范构建、六项 Windows 测试、四轮完整链路和 20 帧生命周期检查的 VPL 版本安装到原反向程序路径。Windows 完整 SHA256 为 `'+installed+'`。替换前的 E1543F07 程序保存在 [install-state.json](method/install-state.json) 所列备份目录。安装入口是针对这两个哈希的一次性脚本，不应直接重跑。\n\n完整链路四轮为 39.55–41.16 个不同画面/秒；绘制前至 Linux 桌面观察的时延估计上界中位 68.15–79.14ms、P95 78.49–85.53ms。它们不等于物理屏幕扫描时延，60ms 目标仍未达到。此前同一候选程序的 MFT/VPL 交叉对照和 90 个共同画面的逐 RGB 像素比较见 [候选记录](../vpl-candidate/README.md) 与 [画质记录](../vpl-quality/README.md)。\n\n已安装控制器真实往返 latency、frame-rate 后恢复原 frame-rate；切换不重启服务。两方向的现有按钮继续可用，模式上限在本次 VPL 测量中未成为瓶颈。Windows 主任务仍 Ready，Linux 主桌面服务仍 inactive，原输入服务仍 active，配置及显示矩形读回一致。**下次开启穿透时使用新程序**；本次没有启动主配对会话，也未注入输入或改变焦点来验收。\n\n旧程序及 mode 文件在替换前校验，临时文件哈希匹配后原子替换；安装失败分支回退旧程序。安装后验证程序哈希、原配置、模式文件、服务、显示和模式读回。回退时应先确认原生反向源未运行，再把备份的 E154 文件恢复到 install-state 中的 target；无需更改源配置。\n')
p=b/'transport/README.md';text=p.read_text();heading='## Direct VPL and canonical automatic selection';text=text.split('\n'+heading)[0];text+='\n'+heading+'\n\n'+table(labels)+'\n\nThere are now 51 qualified full-route trials. The first four rows form a same-binary MFT/VPL A/B/B/A comparison; the last four validate the canonical installed build with its real mode-file controller. VPL improves the candidate comparison, but all latency estimates remain above the 60 ms target at P95. Every logged submission has pending=0, and the one/four-frame bounds are nonbinding. Raw maximum observations, clock envelopes, native identities, nested compositor snapshots and cleanup are retained. [Candidate](../vpl-candidate/README.md), [canonical](../root-vpl/README.md), [installed](../vpl-deployment/README.md).\n';p.write_text(text)
p=b/'README.md';text=p.read_text().replace('最新检查额度剩余34%','最新检查额度剩余32%');old='当前已安装的Windows反向程序为 **E1543F07…**，默认帧率优先，两轮规范版完整链路为 **32.947／33.509FPS**、时延估计上界中位 **80.156／78.406ms**。两个方向各自提供帧率优先／延迟优先；主会话保持未启动，下一次开启使用新版。[部署与回退记录](production-deployment/README.md)。';new='当前已安装的Windows反向程序为 **875E56F9…**，Intel HEVC 自动使用 VPL。规范版四轮完整链路为 **39.55–41.16FPS**、时延估计上界中位 **68.15–79.14ms**、P95 **78.49–85.53ms**。两个方向各自提供帧率优先／延迟优先；主会话保持未启动，下一次开启使用新版。[部署与回退记录](vpl-deployment/README.md)。';text=text.replace(old,new);heading='## Intel VPL 编码路径与当前部署';text=text.split('\n'+heading)[0];text+='\n'+heading+'\n\n新增八轮完整链路测量，总计 51 轮有效记录。同一候选程序的 MFT/VPL 交叉对照中，旧编码器约 32.1–32.7FPS、中位 83.4–88.8ms，VPL 约 40.6–42.1FPS、中位 68.8–69.9ms。规范版复测保留了呈现时序造成的波动，没有把候选最佳中位数当作固定时延保证。[完整对照](transport/README.md#direct-vpl-and-canonical-automatic-selection)。\n\n自有 NV12 纹理通过外部分配接口提交到 VPL，省去应用层额外复制；这不等于驱动内部没有复制。两列 HEVC 分块由运行库实际读回确认。内部纹理输出视图、共享导入和直接 RGB 输入的不支持结果，以及 13 个独立探针记录均保留。\n\n957 帧 MFT 与 1181 帧 VPL 源流全部通过 GPU 解码和透明度检查。90 个共同画面的全部 6K RGB 像素比较得到两者 PSNR 均约 41.8995dB；这仅覆盖该合成图案。规范版通过六项 Windows 测试及 20 帧生命周期检查后已经安装，保留旧程序备份及两个性能选项。**60ms 目标仍未达到**，继续优化并遵守额度剩余 10% 前收尾的要求。\n';p.write_text(text)
for name in ['vpl-candidate','root-vpl','lifecycle-vpl','lifecycle-root-vpl','vpl-quality','vpl-deployment','transport']:
 p=b/name;files=sorted(f for f in p.rglob('*') if f.is_file() and '__pycache__' not in f.parts and f!=p/'sha256.json');write(p/'sha256.json',{str(f.relative_to(p)):sha(f) for f in files})
index_files=[b/'README.md',*sorted((b/'method').glob('*.py')),*sorted((b/'method').glob('vpl-*.json')),*sorted(b.glob('*/sha256.json'))]
write(b/'method/index-sha256.json',{str(p.relative_to(b)):sha(p) for p in index_files})
checked=0
for manifest in b.glob('*/sha256.json'):
 for path,h in read(manifest).items():assert sha(manifest.parent/path)==h,(manifest,path);checked+=1
for path,h in read(b/'method/index-sha256.json').items():assert sha(b/path)==h
print('VPL installation and archive verified',checked,'files',len(index_files),'index entries')
